{"command": "python3 -c "
from PIL import Image, ImageDraw
im=Image.open('radiograph.jpg').convert('RGB')
W,H=im.size
for name,(a,b,c,d) in {'half_L':(0.04,0.20,0.50,0.60),'half_R':(0.50,0.20,0.96,0.60)}.items():
    box=(int(a*W),int(b*H),int(c*W),int(d*H))
    crop=im.crop(box)
    crop=crop.resize((crop.width*2,crop.height*2),Image.LANCZOS)
    dd=ImageDraw.Draw(crop)
    # minor grid every 2% of original
    for i in range(1,50):
        x=int(crop.width*i/46); 
        if x<crop.width: dd.line([(x,0),(x,crop.height)],fill=(255,0,0),width=1)
    crop.save(f'{name}.png'); print(name,crop.size)
"", "description": "Half-image views with fine grid"}
